    "solution": "function buildNmapCommand(target, options) {\n  let cmd = 'nmap';\n  if (options.stealth) cmd += ' -sS';\n  if (options.serviceDetect) cmd += ' -sV';\n  if (options.ports && options.ports.length > 0) cmd += ` -p ${options.ports.join(',')}`;\n  cmd += ` ${target}`;\n  return cmd;\n}",
